      if(!remainder || fpParts(remainder).length!==1 || fpArea(remainder)<40)continue;
      host.poly=remainder;
      rooms.push({poly,type,unit:`S-${type}`,fr,rec:{type,x0:x0+.12,x1:x1-.12,y0:y0+.12,y1:y1-.12},inner:true});
